class Solution:
    def minSumOfLengths(self, arr: list[int], target: int) -> int:
        n = len(arr)
        pref_map = {0: -1}
        cur_sum = 0
        min_len = [float("inf")] * n
        best = float("inf")
        ans = float("inf")
        for i, x in enumerate(arr):
            cur_sum += x
            pref_map[cur_sum] = i
            need = cur_sum - target
            if need in pref_map:
                start_idx = pref_map[need]
                l = i - start_idx
                if start_idx >= 0 and min_len[start_idx] != float("inf"):
                    ans = min(ans, l + min_len[start_idx])
                best = min(best, l)
            min_len[i] = best
        return ans if ans != float("inf") else -1

#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minSumOfLengths(std::vector<int>& arr, int target) {
        int n = arr.size();
        std::unordered_map<int, int> prefMap;
        prefMap[0] = -1;
        int curSum = 0, best = 1e9, ans = 1e9;
        std::vector<int> minLen(n, 1e9);
        for (int i = 0; i < n; ++i) {
            curSum += arr[i];
            prefMap[curSum] = i;
            int need = curSum - target;
            if (prefMap.count(need)) {
                int startIdx = prefMap[need];
                int l = i - startIdx;
                if (startIdx >= 0 && minLen[startIdx] < 1e9) {
                    ans = std::min(ans, l + minLen[startIdx]);
                }
                best = std::min(best, l);
            }
            minLen[i] = best;
        }
        return ans < 1e9 ? ans : -1;
    }
};

import java.util.*;

class Solution {
    public int minSumOfLengths(int[] arr, int target) {
        int n = arr.length;
        Map<Integer, Integer> prefMap = new HashMap<>();
        prefMap.put(0, -1);
        int curSum = 0, best = 1000000000, ans = 1000000000;
        int[] minLen = new int[n];
        Arrays.fill(minLen, 1000000000);
        for (int i = 0; i < n; i++) {
            curSum += arr[i];
            prefMap.put(curSum, i);
            int need = curSum - target;
            if (prefMap.containsKey(need)) {
                int startIdx = prefMap.get(need);
                int l = i - startIdx;
                if (startIdx >= 0 && minLen[startIdx] < 1000000000) {
                    ans = Math.min(ans, l + minLen[startIdx]);
                }
                best = Math.min(best, l);
            }
            minLen[i] = best;
        }
        return ans < 1000000000 ? ans : -1;
    }
}

